112	        double ang = 2.0 * M_PI * frand();
113	        double rad = LIGHT_RADIUS * sqrt(frand());
114	        v3 lp = add(LIGHT_POS, add(mul(u, cos(ang)*rad), mul(v, sin(ang)*rad)));
115	        v3 dir = sub(lp, p);
116	        double dist = sqrt(dot(dir, dir));
117	        dir = mul(dir, 1.0/dist);
118	        int id; double t = intersect(p, dir, &id);
119	        if (id == -2 || t > dist) visible++;
120	    }
121	    return (double)visible / SHADOW_SAMPLES;
122	}
123	
124	static v3 sky(v3 d){
125	    double t = 0.5 * (d.y + 1.0);
126	    v3 horizon = V(0.95, 0.85, 0.75);
127	    v3 zenith  = V(0.35, 0.55, 0.90);
128	    return add(mul(horizon, 1.0 - t), mul(zenith, t));
129	}
130	
131	static v3 shade(v3 o, v3 d, int depth);
132	
133	static v3 surface_color(v3 p, v3 n, v3 d, v3 base, double refl, double spec, int depth){
134	    v3 to_light = norm(sub(LIGHT_POS, p));
135	    double vis = light_visibility(p);
136	    double diff = fmax(0.0, dot(n, to_light)) * vis * LIGHT_INTENSITY;
137	    v3 col = mul(hadamard(base, LIGHT_COLOR), AMBIENT + diff);
138	
139	    /* phong highlight */
140	    if (spec > 0 && vis > 0){
141	        v3 h = norm(sub(to_light, d));
142	        double s = pow(fmax(0.0, dot(n, h)), spec) * vis * LIGHT_INTENSITY;
143	        col = add(col, mul(LIGHT_COLOR, s * 0.6));
144	    }
145	    /* reflection */
146	    if (refl > 0 && depth < MAX_DEPTH){
147	        v3 r = shade(p, norm(reflect(d, n)), depth + 1);
148	        col = add(mul(col, 1.0 - refl), mul(r, refl));
149	    }
150	    return col;
151	}
152	
153	static v3 shade(v3 o, v3 d, int depth){
154	    int id;
155	    double t = intersect(o, d, &id);
156	    if (id == -2) return sky(d);
157	    v3 p = add(o, mul(d, t));
158	
159	    if (id == -1){
160	        /* checkerboard floor */
161	        int check = ((int)floor(p.x) + (int)floor(p.z)) & 1;
162	        v3 base = check ? V(0.92, 0.92, 0.9) : V(0.18, 0.18, 0.2);
163	        /* fade the floor to sky color in the distance */
164	        v3 col = surface_color(p, V(0,1,0), d, base, 0.22, 0.0, depth);
165	        double fog = fmin(1.0, t / 45.0);
166	        return add(mul(col, 1.0 - fog), mul(sky(d), fog));
167	    }
168	    const sphere *s = &spheres[id];
169	    v3 n = norm(sub(p, s->center));
170	    return surface_color(p, n, d, s->color, s->reflectivity, s->specular, depth);
171	}
172	
173	/* ---------- PNG writer (stored deflate, no libs) ---------- */
174	static uint32_t crc_table[256];
175	static void crc_init(void){
176	    for (uint32_t n = 0; n < 256; n++){
177	        uint32_t c = n;
178	        for (int k = 0; k < 8; k++)
179	            c = (c & 1) ? 0xedb88320u ^ (c >> 1) : c >> 1;
180	        crc_table[n] = c;
181	    }
182	}
183	static uint32_t crc32_buf(uint32_t crc, const uint8_t *buf, size_t len){
184	    crc = ~crc;
185	    for (size_t i = 0; i < len; i++)
186	        crc = crc_table[(crc ^ buf[i]) & 0xff] ^ (crc >> 8);
187	    return ~crc;
188	}
189	static void be32(uint8_t *p, uint32_t v){
190	    p[0]=v>>24; p[1]=v>>16; p[2]=v>>8; p[3]=v;
191	}
192	static void chunk(FILE *f, const char *type, const uint8_t *data, uint32_t len){
193	    uint8_t hdr[8];
194	    be32(hdr, len);
195	    memcpy(hdr+4, type, 4);
196	    fwrite(hdr, 1, 8, f);
197	    if (len) fwrite(data, 1, len, f);
198	    uint32_t crc = crc32_buf(0, hdr+4, 4);
199	    crc = crc32_buf(crc, data, len);
200	    uint8_t tail[4]; be32(tail, crc);
201	    fwrite(tail, 1, 4, f);
202	}
203	static void write_png(const char *path, const uint8_t *rgb, int w, int h){
204	    crc_init();
205	    FILE *f = fopen(path, "wb");
206	    if (!f){ perror(path); exit(1); }
207	    const uint8_t sig[8] = {137,80,78,71,13,10,26,10};
208	    fwrite(sig, 1, 8, f);
209	
210	    uint8_t ihdr[13];
211	    be32(ihdr, (uint32_t)w); be32(ihdr+4, (uint32_t)h);
212	    ihdr[8]=8; ihdr[9]=2; ihdr[10]=0; ihdr[11]=0; ihdr[12]=0; /* 8-bit RGB */
213	    chunk(f, "IHDR", ihdr, 13);
214	
215	    /* raw scanlines: filter byte 0 + w*3 bytes each */
216	    size_t rowlen = 1 + (size_t)w*3;
217	    size_t rawlen = rowlen * h;
218	    uint8_t *raw = malloc(rawlen);
219	    for (int y = 0; y < h; y++){
220	        raw[y*rowlen] = 0;
221	        memcpy(raw + y*rowlen + 1, rgb + (size_t)y*w*3, (size_t)w*3);
222	    }
223	    /* zlib stream with stored deflate blocks (max 65535 bytes each) */
224	    size_t nblocks = (rawlen + 65534) / 65535;
225	    size_t zlen = 2 + rawlen + nblocks*5 + 4;
226	    uint8_t *z = malloc(zlen);
227	    size_t zi = 0;
228	    z[zi++] = 0x78; z[zi++] = 0x01; /* zlib header, no dict */
229	    size_t off = 0;
230	    while (off < rawlen){
231	        size_t n = rawlen - off; if (n > 65535) n = 65535;
232	        z[zi++] = (off + n == rawlen) ? 1 : 0; /* BFINAL */
233	        z[zi++] = n & 0xff; z[zi++] = n >> 8;
234	        z[zi++] = ~n & 0xff; z[zi++] = (~n >> 8) & 0xff;
235	        memcpy(z + zi, raw + off, n);
236	        zi += n; off += n;
237	    }
238	    /* adler32 of raw data */
239	    uint32_t a = 1, b = 0;
240	    for (size_t i = 0; i < rawlen; i++){
241	        a = (a + raw[i]) % 65521;
242	        b = (b + a) % 65521;
243	    }
244	    be32(z + zi, (b << 16) | a); zi += 4;
245	    chunk(f, "IDAT", z, (uint32_t)zi);
246	    chunk(f, "IEND", NULL, 0);
247	    fclose(f);
248	    free(raw); free(z);
249	}
250	
251	/* ---------- main ---------- */
252	int main(int argc, char **argv){
253	    const char *out = argc > 1 ? argv[1] : "out.png";
254	    const int W = 1280, H = 800, SPP = 8; /* 2x2 jittered supersampling */
255	
256	    v3 cam = V(0.0, 1.8, 6.5);
257	    v3 look = V(0.0, 0.8, 0.0);
258	    v3 fwd = norm(sub(look, cam));
259	    v3 right = norm(V(-fwd.z, 0, fwd.x)); /* fwd x worldUp */
260	    v3 up = V(right.y*fwd.z - right.z*fwd.y,
261	              right.z*fwd.x - right.x*fwd.z,
262	              right.x*fwd.y - right.y*fwd.x);
263	    double fov = 0.9; /* ~52 deg vertical */
264	    double aspect = (double)W / H;
265	
266	    uint8_t *img = malloc((size_t)W*H*3);
267	    for (int y = 0; y < H; y++){
268	        for (int x = 0; x < W; x++){
269	            v3 acc = V(0,0,0);
270	            for (int s = 0; s < SPP; s++){
271	                double jx = ((s & 1) + frand()) * 0.5;
272	                double jy = ((s >> 1) + frand()) * 0.5;
273	                double u = ((x + jx) / W * 2.0 - 1.0) * tan(fov/2) * aspect;
274	                double v = (1.0 - (y + jy) / H * 2.0) * tan(fov/2);
275	                v3 d = norm(add(fwd, add(mul(right, u), mul(up, v))));
276	                acc = add(acc, shade(cam, d, 0));
277	            }
278	            acc = mul(acc, 1.0 / SPP);
279	            uint8_t *px = img + ((size_t)y*W + x)*3;
280	            /* gamma 2.2 and clamp */
281	            px[0] = (uint8_t)(255.0 * fmin(1.0, pow(fmax(0.0, acc.x), 1/2.2)));
282	            px[1] = (uint8_t)(255.0 * fmin(1.0, pow(fmax(0.0, acc.y), 1/2.2)));
283	            px[2] = (uint8_t)(255.0 * fmin(1.0, pow(fmax(0.0, acc.z), 1/2.2)));
284	        }
285	        if (y % 60 == 0) fprintf(stderr, "row %d/%d\n", y, H);
286	    }
287	    write_png(out, img, W, H);
288	    free(img);
289	    fprintf(stderr, "wrote %s (%dx%d)\n", out, W, H);
290	    return 0;
291	}
