#define main disabled_main
#include "trace.c"
#undef main

int main(void){
    const int W = 1280, H = 800;
    v3 cam = V(0.0, 1.8, 6.5);
    v3 look = V(0.0, 0.8, 0.0);
    v3 fwd = norm(sub(look, cam));
    v3 right = norm(V(-fwd.z, 0, fwd.x));
    v3 up = V(right.y*fwd.z - right.z*fwd.y,
              right.z*fwd.x - right.x*fwd.z,
              right.x*fwd.y - right.y*fwd.x);
    double fov = 0.9, aspect = (double)W/H;
    int pts[][2] = {{300,650},{980,650},{300,500},{980,500},{560,600},{720,600}};
    for (int i = 0; i < 6; i++){
        int x = pts[i][0], y = pts[i][1];
        double u = ((x + 0.5) / W * 2.0 - 1.0) * tan(fov/2) * aspect;
        double v = (1.0 - (y + 0.5) / H * 2.0) * tan(fov/2);
        v3 d = norm(add(fwd, add(mul(right, u), mul(up, v))));
        int id; double t = intersect(cam, d, &id);
        v3 p = add(cam, mul(d, t));
        v3 c = shade(cam, d, 0);
        int r = (int)(255.0*fmin(1.0,pow(fmax(0.0,c.x),1/2.2)));
        int g = (int)(255.0*fmin(1.0,pow(fmax(0.0,c.y),1/2.2)));
        int b = (int)(255.0*fmin(1.0,pow(fmax(0.0,c.z),1/2.2)));
        printf("pix(%4d,%4d) hit id=%2d world=(%6.2f,%5.2f,%6.2f)  rgb=(%3d,%3d,%3d)\n",
               x, y, id, p.x, p.y, p.z, r, g, b);
    }
    return 0;
}
